    test("redactConversation (3)", async () => {
        const server = mockServerPool.createServer();
        const client = new IntercomClient({
            maxRetries: 0,
            token: "test",
            version: "2.14",
            environment: server.baseUrl,
        });
        const rawRequestBody = {
            type: "conversation_part",
            conversation_id: "conversation_id",
            conversation_part_id: "conversation_part_id",
        };
        const rawResponseBody = { type: "type", errors: [{ code: "code" }, { code: "code" }] };
        server
            .mockEndpoint()
            .post("/conversations/redact")
            .jsonBody(rawRequestBody)
            .respondWith()
            .statusCode(401)
            .jsonBody(rawResponseBody)
            .build();

        await expect(async () => {
            return await client.preview.conversationParts.redactConversation({
                type: "conversation_part",
                conversation_id: "conversation_id",
                conversation_part_id: "conversation_part_id",
            });
        }).rejects.toThrow(Intercom.preview.UnauthorizedError);
    });

